'use server';

/**
 * Server actions for the site editor.
 *
 * Security model:
 *   - Every action calls `requireCustomerSiteAccess(siteId)` first (fail-closed).
 *   - `siteId` comes from a hidden form field and is checked BEFORE any Sanity
 *     read, closing the IDOR vector.
 *   - Only paths generated by the fields registry are ever written to Sanity.
 *     The patch set is built server-side from `buildPatchSet` — no client path
 *     is trusted.
 *   - Hard-blocked fields (draftMode, robotsDisallow, slug, etc.) are never
 *     in the allowlist and are explicitly locked in `publishSite` before the
 *     promote action.
 */

import { redirect } from 'next/navigation';
import { revalidatePath } from 'next/cache';
import {
  requireCustomerSiteAccess,
  UnauthorizedError,
} from '@/lib/auth-guard';
import {
  getEditableDoc,
  saveFields,
  publishSite,
  discardDraft,
  uploadAndSetImage,
  getAiImageGenerationCount,
  incrementAiImageGenerationCount,
  AI_IMAGE_GENERATION_LIMIT,
  writeSections,
  genKey,
  regenerateKeys,
  type CustomerLayout,
} from '@/lib/sanity-write';
import { validateFormValues, buildPatchSet, isSafeKey } from '@/lib/fields';
import { BS_SECTION_RULES, seedSection, type BsSectionType } from '@leadlandlord/shared';
import { generateHeroImageBuffer } from '@leadlandlord/integrations/imagen';

// ---------------------------------------------------------------------------
// Save action
// ---------------------------------------------------------------------------

export interface SaveResult {
  ok: boolean;
  errors?: Record<string, string>;
  message?: string;
  /** True when the save succeeded but there was nothing to write. */
  noop?: boolean;
}

/**
 * Validates submitted form values and patches the Sanity draft.
 *
 * FormData must include a `siteId` hidden field. All other entries are treated
 * as potential field values and validated against the zod allowlist.
 */
export async function saveAction(_prev: SaveResult, formData: FormData): Promise<SaveResult> {
  const siteId = String(formData.get('siteId') ?? '').trim();
  if (!siteId) return { ok: false, message: 'Missing site ID.' };

  // Auth guard first — before any Sanity read.
  try {
    await requireCustomerSiteAccess(siteId);
  } catch (err) {
    if (err instanceof UnauthorizedError) {
      redirect('/login');
    }
    return { ok: false, message: 'Access denied.' };
  }

  // Collect form values (everything except siteId).
  const raw: Record<string, string> = {};
  for (const [key, value] of formData.entries()) {
    if (key === 'siteId') continue;
    if (typeof value === 'string') {
      raw[key] = value;
    }
  }

  // Read current doc to resolve sub-array _key values and build the
  // key-to-type map needed for precise schema validation of section fields.
  const doc = await getEditableDoc(siteId);
  if (!doc) {
    return { ok: false, message: 'Site content not found. It may still be building.' };
  }

  // Build sectionKey -> _type map from the doc for schema resolution.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const keyTypeMap: Record<string, string> = {};
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  if (Array.isArray((doc as any).sections)) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    for (const s of (doc as any).sections as Array<{ _key?: string; _type?: string }>) {
      if (s._key && s._type) keyTypeMap[s._key] = s._type;
    }
  }

  // Validate against the allowlist zod schemas.
  const validation = validateFormValues(raw, keyTypeMap);
  if (!validation.ok) {
    return { ok: false, errors: validation.errors };
  }

  // Build granular Sanity patch paths.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const patchSet = buildPatchSet(doc as Record<string, any>, validation.values);

  if (Object.keys(patchSet).length === 0) {
    return { ok: true, noop: true }; // Nothing changed.
  }

  try {
    await saveFields(siteId, patchSet);
  } catch (err) {
    return {
      ok: false,
      message: err instanceof Error ? err.message : 'Save failed. Please try again.',
    };
  }

  revalidatePath(`/sites/${siteId}/edit`);
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Publish action
// ---------------------------------------------------------------------------

export interface PublishResult {
  ok: boolean;
  message?: string;
}

/**
 * Promotes the draft to published. Sets safety locks (draftMode:false,
 * robotsDisallow:false) before the atomic promote action.
 */
export async function publishAction(siteId: string): Promise<PublishResult> {
  if (!siteId) return { ok: false, message: 'Missing site ID.' };

  try {
    await requireCustomerSiteAccess(siteId);
  } catch (err) {
    if (err instanceof UnauthorizedError) {
      redirect('/login');
    }
    return { ok: false, message: 'Access denied.' };
  }

  try {
    await publishSite(siteId);
    revalidatePath(`/sites/${siteId}/edit`);
    return { ok: true };
  } catch (err) {
    return {
      ok: false,
      message: err instanceof Error ? err.message : 'Publish failed. Please try again.',
    };
  }
}

// ---------------------------------------------------------------------------
// Discard action
// ---------------------------------------------------------------------------

export interface DiscardResult {
  ok: boolean;
  message?: string;
}

/**
 * Discards the draft, reverting to the last published version.
 */
export async function discardAction(siteId: string): Promise<DiscardResult> {
  if (!siteId) return { ok: false, message: 'Missing site ID.' };

  try {
    await requireCustomerSiteAccess(siteId);
  } catch (err) {
    if (err instanceof UnauthorizedError) {
      redirect('/login');
    }
    return { ok: false, message: 'Access denied.' };
  }

  try {
    await discardDraft(siteId);
    revalidatePath(`/sites/${siteId}/edit`);
    return { ok: true };
  } catch (err) {
    return {
      ok: false,
      message: err instanceof Error ? err.message : 'Discard failed. Please try again.',
    };
  }
}

// ---------------------------------------------------------------------------
// Image upload action
// ---------------------------------------------------------------------------

/**
 * Allowed image field keys. Must stay in sync with IMAGE_FIELD_PATHS in
 * lib/sanity-write.ts. Checked here (server action boundary) before
 * uploadAndSetImage also validates.
 */
const ALLOWED_IMAGE_FIELD_KEYS = new Set([
  'logo',
  'favicon',
  'hero.image',
  'about.image',
  'seo.ogImage',
]);

export interface UploadImageResult {
  ok: boolean;
  assetUrl?: string;
  error?: string;
}

/**
 * Uploads an image file for one of the permitted image fields and
 * patches the Sanity draft.
 *
 * FormData must contain:
 *   - `file`     — the File object
 *   - `fieldKey` — one of 'logo' | 'favicon' | 'hero.image' | 'about.image' | 'seo.ogImage'
 *
 * Security:
 *   - `requireCustomerSiteAccess(siteId)` is called first (fail-closed).
 *   - fieldKey is validated against the hard-coded allowlist.
 *   - contentType and byte-length are validated server-side (not trusted from client).
 */
export async function uploadImageAction(
  siteId: string,
  fieldKey: string,
  formData: FormData,
): Promise<UploadImageResult> {
  if (!siteId) return { ok: false, error: 'Missing site ID.' };

  // 1. Auth guard first.
  try {
    await requireCustomerSiteAccess(siteId);
  } catch (err) {
    if (err instanceof UnauthorizedError) {
      redirect('/login');
    }
    return { ok: false, error: 'Access denied.' };
  }

  // 2. Allowlist check on fieldKey.
  if (!ALLOWED_IMAGE_FIELD_KEYS.has(fieldKey)) {
    return { ok: false, error: `Image field '${fieldKey}' is not permitted.` };
  }

  // 3. Read the File from FormData.
  const file = formData.get('file');
  if (!(file instanceof File)) {
    return { ok: false, error: 'No file provided.' };
  }

  if (file.size === 0) {
    return { ok: false, error: 'File is empty.' };
  }

  // 4. Validate content type from the File object (declared by the browser,
  //    but we also rely on uploadAndSetImage to enforce it).
  const contentType = file.type;

  // 5. Convert to Buffer for the Sanity upload API.
  const arrayBuffer = await file.arrayBuffer();
  const buffer = Buffer.from(arrayBuffer);

  // 6. Delegate to the write helper (validates type + size + allowlist again).
  try {
    const result = await uploadAndSetImage(siteId, fieldKey, {
      buffer,
      filename: file.name,
      contentType,
    });
    return { ok: true, assetUrl: result.assetUrl };
  } catch (err) {
    return {
      ok: false,
      error: err instanceof Error ? err.message : 'Upload failed. Please try again.',
    };
  }
}

// ---------------------------------------------------------------------------
// AI image generation (Google Imagen)
// ---------------------------------------------------------------------------

/** Target field -> Imagen aspect ratio. Also serves as the allowlist. */
const GENERATE_ASPECT: Record<string, '16:9' | '4:3' | '1:1' | '3:2'> = {
  'logo': '1:1',
  'hero.image': '16:9',
  'about.image': '4:3',
  'seo.ogImage': '16:9',
};

export interface GenerateImageResult {
  ok: boolean;
  assetUrl?: string;
  /** Generations remaining for this site after this call. */
  remaining?: number;
  error?: string;
}

/**
 * Generates an image from a customer prompt via Google Imagen, uploads it to
 * Sanity, and sets it on the chosen image field of the draft.
 *
 * Security / limits:
 *   - `requireCustomerSiteAccess(siteId)` first (fail-closed).
 *   - `fieldKey` validated against GENERATE_ASPECT (same four image targets).
 *   - Hard cap of AI_IMAGE_GENERATION_LIMIT per site, enforced server-side on a
 *     counter stored on the PUBLISHED doc. Only successful generations count.
 */
export async function generateImageAction(
  siteId: string,
  fieldKey: string,
  prompt: string,
): Promise<GenerateImageResult> {
  if (!siteId) return { ok: false, error: 'Missing site ID.' };

  // 1. Auth guard first.
  try {
    await requireCustomerSiteAccess(siteId);
  } catch (err) {
    if (err instanceof UnauthorizedError) {
      redirect('/login');
    }
    return { ok: false, error: 'Access denied.' };
  }

  // 2. Target allowlist.
  const aspectRatio = GENERATE_ASPECT[fieldKey];
  if (!aspectRatio) {
    return { ok: false, error: `Image field '${fieldKey}' is not permitted.` };
  }

  // 3. Prompt validation.
  const clean = (prompt ?? '').trim();
  if (clean.length < 3) return { ok: false, error: 'Please describe the image you want (a few words).' };
  if (clean.length > 500) return { ok: false, error: 'Description is too long (max 500 characters).' };
  if (clean.includes('<')) return { ok: false, error: 'Description contains invalid characters.' };

  // 4. Usage limit — check BEFORE spending on generation.
  const used = await getAiImageGenerationCount(siteId);
  if (used >= AI_IMAGE_GENERATION_LIMIT) {
    return {
      ok: false,
      remaining: 0,
      error: `You've used all ${AI_IMAGE_GENERATION_LIMIT} AI image generations for this site.`,
    };
  }

  // 5. Generate the image.
  let img;
  try {
    img = await generateHeroImageBuffer(clean, {
      aspectRatio,
      negativePrompt: 'text, words, letters, watermark, signature, blurry, low quality, distorted',
    });
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : 'Image generation failed. Please try again.' };
  }
  if (!img) {
    return {
      ok: false,
      error: 'Image generation is currently unavailable. Please upload your own image instead.',
    };
  }

  // 6. Upload + set on the chosen field (reuses type/size/magic-byte validation
  //    and the draft patch), then count the successful generation.
  try {
    const ext = img.contentType === 'image/png' ? 'png' : 'jpg';
    const result = await uploadAndSetImage(siteId, fieldKey, {
      buffer: img.buffer,
      filename: `ai-${fieldKey.replace(/[^a-z0-9]+/gi, '-')}.${ext}`,
      contentType: img.contentType,
    });
    const newUsed = await incrementAiImageGenerationCount(siteId);
    revalidatePath(`/sites/${siteId}/edit`);
    return {
      ok: true,
      assetUrl: result.assetUrl,
      remaining: Math.max(0, AI_IMAGE_GENERATION_LIMIT - newUsed),
    };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : 'Could not save the generated image.' };
  }
}

// ---------------------------------------------------------------------------
// Structural action helpers
// ---------------------------------------------------------------------------

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AnyDoc = Record<string, any>;

/**
 * Reads the current sections array and customerLayout from the editable doc.
 * Throws a descriptive error if the doc is unavailable.
 */
async function readCurrentSections(siteId: string): Promise<{
  sections: Array<Record<string, unknown>>;
  layout: CustomerLayout;
}> {
  const doc = await getEditableDoc(siteId) as AnyDoc | null;
  if (!doc) throw new Error('Site content not found. It may still be building.');

  const sections: Array<Record<string, unknown>> = Array.isArray(doc.sections)
    ? (doc.sections as Array<Record<string, unknown>>)
    : [];

  const existing = doc.customerLayout as Partial<CustomerLayout> | undefined;
  const layout: CustomerLayout = {
    sectionOrder: existing?.sectionOrder ?? sections.map((s) => String(s._key ?? '')).filter(Boolean),
    removedKeys: existing?.removedKeys ?? [],
    customerOwnedKeys: existing?.customerOwnedKeys ?? [],
    lockedAt: existing?.lockedAt,
  };

  return { sections, layout };
}

/**
 * Refuses structural edits if the site has been handed off (lockedAt is set).
 */
function assertNotLocked(layout: CustomerLayout): void {
  if (layout.lockedAt) {
    throw new Error(
      'This site has been handed off and its structure is locked. Text edits are still allowed.',
    );
  }
}

// ---------------------------------------------------------------------------
// D2 — Structural server actions
// ---------------------------------------------------------------------------

export interface StructuralResult {
  ok: boolean;
  message?: string;
  /** Returned by addSectionAction — the new section _key. */
  newKey?: string;
}

/**
 * Reorders sections by the provided key list (exact permutation of existing keys).
 * Client sends only keys, never block content — blocks are re-ordered server-side
 * from the freshly-read doc.
 */
export async function reorderSectionsAction(
  siteId: string,
  orderedKeys: string[],
): Promise<StructuralResult> {
  if (!siteId) return { ok: false, message: 'Missing site ID.' };

  try {
    await requireCustomerSiteAccess(siteId);
  } catch (err) {
    if (err instanceof UnauthorizedError) redirect('/login');
    return { ok: false, message: 'Access denied.' };
  }

  try {
    const { sections, layout } = await readCurrentSections(siteId);
    assertNotLocked(layout);

    const existingKeys = sections.map((s) => String(s._key ?? ''));

    // Validate: same length, same members, all keys safe.
    if (orderedKeys.length !== existingKeys.length) {
      return { ok: false, message: 'Key list length mismatch.' };
    }
    for (const k of orderedKeys) {
      if (!isSafeKey(k)) return { ok: false, message: `Unsafe key: '${k}'.` };
    }
    const existingSet = new Set(existingKeys);
    const orderedSet = new Set(orderedKeys);
    if (existingSet.size !== orderedSet.size || ![...existingSet].every((k) => orderedSet.has(k))) {
      return { ok: false, message: 'Ordered keys must be an exact permutation of existing section keys.' };
    }

    // Re-order blocks server-side (never trust client block content).
    const sectionByKey = new Map(sections.map((s) => [String(s._key), s]));
    const reordered = orderedKeys.map((k) => sectionByKey.get(k)!);

    layout.sectionOrder = orderedKeys;

    await writeSections(siteId, reordered, layout);
    return { ok: true };
  } catch (err) {
    return { ok: false, message: err instanceof Error ? err.message : 'Reorder failed.' };
  }
}

/**
 * Adds a new section of the given type before the footer section.
 * Returns the new section's _key on success.
 */
export async function addSectionAction(
  siteId: string,
  sectionType: string,
): Promise<StructuralResult> {
  if (!siteId) return { ok: false, message: 'Missing site ID.' };

  try {
    await requireCustomerSiteAccess(siteId);
  } catch (err) {
    if (err instanceof UnauthorizedError) redirect('/login');
    return { ok: false, message: 'Access denied.' };
  }

  // Validate the type is a known addable type.
  const rule = BS_SECTION_RULES[sectionType as BsSectionType];
  if (!rule) return { ok: false, message: `Unknown section type: '${sectionType}'.` };
  if (!rule.addable) return { ok: false, message: `Section type '${rule.label}' cannot be added.` };

  try {
    const { sections, layout } = await readCurrentSections(siteId);
    assertNotLocked(layout);

    // Server-side singleton check: if addable is true, singleton is false per the rules,
    // but double-check defensively.
    if (rule.singleton) {
      const alreadyPresent = sections.some((s) => s._type === sectionType);
      if (alreadyPresent) {
        return { ok: false, message: `Only one '${rule.label}' section is allowed.` };
      }
    }

    // Seed the new section and assign a generated _key.
    const seed = seedSection(sectionType as BsSectionType) as Record<string, unknown>;
    const newKey = genKey(sectionTypePrefix(sectionType));
    seed._key = newKey;

    // Insert before the footer section (if present), else append.
    const footerIndex = sections.findIndex((s) => s._type === 'bsFooterSection');
    const newSections = [...sections];
    if (footerIndex !== -1) {
      newSections.splice(footerIndex, 0, seed);
    } else {
      newSections.push(seed);
    }

    // Update layout.
    const newOrder = newSections.map((s) => String(s._key));
    layout.sectionOrder = newOrder;
    if (!layout.customerOwnedKeys.includes(newKey)) {
      layout.customerOwnedKeys = [...layout.customerOwnedKeys, newKey];
    }

    await writeSections(siteId, newSections, layout);
    return { ok: true, newKey };
  } catch (err) {
    return { ok: false, message: err instanceof Error ? err.message : 'Add section failed.' };
  }
}

/**
 * Removes a section by _key. Refuses to remove required singletons.
 */
export async function removeSectionAction(
  siteId: string,
  sectionKey: string,
): Promise<StructuralResult> {
  if (!siteId) return { ok: false, message: 'Missing site ID.' };
  if (!isSafeKey(sectionKey)) return { ok: false, message: 'Invalid section key.' };

  try {
    await requireCustomerSiteAccess(siteId);
  } catch (err) {
    if (err instanceof UnauthorizedError) redirect('/login');
    return { ok: false, message: 'Access denied.' };
  }

  try {
    const { sections, layout } = await readCurrentSections(siteId);
    assertNotLocked(layout);

    const target = sections.find((s) => String(s._key) === sectionKey);
    if (!target) return { ok: false, message: 'Section not found.' };

    const sectionType = String(target._type ?? '');
    const rule = BS_SECTION_RULES[sectionType as BsSectionType];
    if (!rule) return { ok: false, message: `Unknown section type '${sectionType}'.` };
    if (!rule.removable) {
      return { ok: false, message: `The '${rule.label}' section cannot be removed.` };
    }

    const newSections = sections.filter((s) => String(s._key) !== sectionKey);
    const newOrder = newSections.map((s) => String(s._key));
    layout.sectionOrder = newOrder;
    layout.removedKeys = [...layout.removedKeys, sectionKey];
    // Remove from customerOwnedKeys if present.
    layout.customerOwnedKeys = layout.customerOwnedKeys.filter((k) => k !== sectionKey);

    await writeSections(siteId, newSections, layout);
    return { ok: true };
  } catch (err) {
    return { ok: false, message: err instanceof Error ? err.message : 'Remove section failed.' };
  }
}

/**
 * Duplicates a section by _key. Rejects singletons. Regenerates all nested keys.
 * Inserts the clone immediately after the source.
 */
export async function duplicateSectionAction(
  siteId: string,
  sectionKey: string,
): Promise<StructuralResult> {
  if (!siteId) return { ok: false, message: 'Missing site ID.' };
  if (!isSafeKey(sectionKey)) return { ok: false, message: 'Invalid section key.' };

  try {
    await requireCustomerSiteAccess(siteId);
  } catch (err) {
    if (err instanceof UnauthorizedError) redirect('/login');
    return { ok: false, message: 'Access denied.' };
  }

  try {
    const { sections, layout } = await readCurrentSections(siteId);
    assertNotLocked(layout);

    const sourceIndex = sections.findIndex((s) => String(s._key) === sectionKey);
    if (sourceIndex === -1) return { ok: false, message: 'Section not found.' };

    const source = sections[sourceIndex]!;
    const sectionType = String(source._type ?? '');
    const rule = BS_SECTION_RULES[sectionType as BsSectionType];
    if (!rule) return { ok: false, message: `Unknown section type '${sectionType}'.` };
    if (rule.singleton) {
      return { ok: false, message: `The '${rule.label}' section cannot be duplicated.` };
    }

    // Deep-clone and regenerate all _keys.
    const clone = regenerateKeys(source);
    const newKey = String(clone._key);

    // Insert immediately after the source.
    const newSections = [...sections];
    newSections.splice(sourceIndex + 1, 0, clone);

    const newOrder = newSections.map((s) => String(s._key));
    layout.sectionOrder = newOrder;
    if (!layout.customerOwnedKeys.includes(newKey)) {
      layout.customerOwnedKeys = [...layout.customerOwnedKeys, newKey];
    }

    await writeSections(siteId, newSections, layout);
    return { ok: true, newKey };
  } catch (err) {
    return { ok: false, message: err instanceof Error ? err.message : 'Duplicate section failed.' };
  }
}

/** Maps a section _type to a short key prefix for genKey. */
function sectionTypePrefix(type: string): string {
  const map: Record<string, string> = {
    bsHeroSection: 'hero',
    bsServicesSection: 'svc',
    bsAboutSection: 'abt',
    bsProcessSection: 'prc',
    bsReviewsSection: 'rev',
    bsContactSection: 'cnt',
    bsUgcSection: 'ugc',
    bsFaqSection: 'faq',
    bsFooterSection: 'ftr',
  };
  return map[type] ?? 'sec';
}
